/* Design-only fixture. No device APIs, credentials, storage or app code. */
const root = '../../../';
let icons = {};
const icon = name => `<svg data-icon="${name}" class="icon" viewBox="0 0 24 24" aria-hidden="true">${icons[name] || icons.gear || ''}</svg>`;
const go = (id, label, kind = '') => `<button class="btn ${kind}" data-go="${id}">${label}</button>`;
const action = (label, kind = '', msg = 'Demonstration only') => `<button class="btn ${kind}" data-message="${msg}">${label}</button>`;
const ib = (name, label, target) => `<button class="iconbtn" aria-label="${label}" ${target ? `data-go="${target}"` : `data-message="${label} · simulated"`}>${icon(name)}</button>`;
const group = content => `<div class="group">${content}</div>`;
function row(label, value = '', target = '', glyph = '') {
  const [name, detail] = label.split('|');
  const tag = target ? 'button' : 'div';
  return `<${tag} class="row" ${target ? `data-go="${target}"` : ''}>${glyph ? icon(glyph) : ''}<span class="text"><strong>${name}</strong>${detail ? `<small>${detail}</small>` : ''}</span>${value ? `<span class="value">${value}</span>` : ''}${target ? `<span class="chev">${icon('back')}</span>` : ''}</${tag}>`;
}
function toggle(label, checked = false) { return `<div class="row">${prayerNames.includes(label)?icon(label.toLowerCase()):''}<span class="text">${label}</span><button class="switch" role="switch" aria-label="${label}" aria-checked="${checked}"><span></span></button></div>`; }
function num(label, value = 0, unit = 'min', min = -30, max = 30, step = 1) {return `<div class="row numeric">${[...prayerNames,'Sunrise'].includes(label)?icon(label.toLowerCase()):''}<span class="text">${label}<small>${unit}</small></span><div class="stepper" data-min="${min}" data-max="${max}" data-step="${step}"><button aria-label="Decrease ${label}" data-delta="-1">−</button><output aria-label="${label}" aria-live="polite">${value}</output><button aria-label="Increase ${label}" data-delta="1">+</button></div></div>`;}
function seg(label, choices, selected = choices[0], stack = false) {return `<div class="seg ${stack ? 'stack' : ''} ${choices.length===5&&stack?'modes':''}" role="group" aria-label="${label}">${choices.map(c=>`<button aria-pressed="${c === selected}">${c}</button>`).join('')}</div>`;}
const weekdays = ['Monday','Tuesday','Wednesday','Thursday','Friday','Saturday','Sunday'];
function days(work = false) {return `<div class="days" role="group" aria-label="Days of the week">${weekdays.map((d,i)=>`<button aria-label="${d}" aria-pressed="${!work || i < 5}"><span>${d[0]}</span></button>`).join('')}</div>`;}
const field = (label, value = '', type = 'text') => `<label class="field"><span>${label}</span><input type="${type}" value="${value}" ${type==='password'?'autocomplete="off"':''}></label>`;
const selectrow = (label, value, target) => `<div class="selectfield" role="group" aria-label="${label}"><span>${label}</span>${row(value, '', target)}</div>`;
const status = (text, name='bell') => `<div class="status">${icon(name)}<span>${text}</span></div>`;
const footer = (primary, target, secondary = '', secondaryTarget = '') => `<footer class="foot">${secondary ? go(secondaryTarget,secondary,'text') : ''}${go(target,primary,'primary')}</footer>`;
const apply = (label = 'Save changes', target = 'settings') => `<footer class="foot"><div class="pair">${go(target,'Cancel','text')}${go(target,label,'primary')}</div></footer>`;
function nav(active='Prayer') {return `<nav class="bottomnav" aria-label="App navigation">${[['Prayer','home','mihrab'],['Your TVs','tvs','tv'],['Settings','settings','gear']].map(([n,id,g])=>`<button class="${n===active?'active':''}" data-go="${id}">${icon(g)}${n}</button>`).join('')}</nav>`;}
const hero = (alert = 'Adhan') => `<div class="hero"><div class="overline">Next prayer · Cairo</div><div class="split"><div class="big">Dhuhr</div><div class="time">11:41</div></div><div class="remaining">In 24 minutes · ${alert}</div></div>`;
const prayerNames = ['Fajr','Dhuhr','Asr','Maghrib','Isha'];
const times = ['04:51','11:41','14:37','16:58','18:17'];
function prayers() {return group(prayerNames.map((n,i)=>row(n,times[i],`prayer-${n.toLowerCase()}`, n.toLowerCase())).join(''));}
function locationFields() {return `<div class="fieldline"><div style="flex:1">${selectrow('Country','Egypt','countries')}</div>${ib('compass','Use my location','detected')}</div>${selectrow('City','Cairo','cities')}${status('<strong>Africa/Cairo</strong><br>Times follow this location.','globe')}`;}
function styleRail(type = 'Theme') {
  const list = type==='Theme' ? [['Miqat','#E3C07D','#F7F0DF','#ADC8C6'],['Aurora','#A8E7CC','#F0F9F3','#BAD4D5'],['Dusk','#F4B8A4','#FFF1E9','#CEBBCF'],['Frost','#D7E8E7','#F4F6EF','#C2D2D5']] : [['Signature'],['Quiet'],['Aurora sky'],['Dusk peaks'],['Plain']];
  return `<div class="rail" role="group" aria-label="${type}">${list.map((c,i)=>`<button class="tile" data-${type==='Theme'?'theme':'background'}="${c[0].toLowerCase()}" aria-pressed="${i===0}">${type==='Theme'?`<span class="swatches">${c.slice(1).map(v=>`<i style="background:${v}"></i>`).join('')}</span>`:`<span style="display:block;${c[0]==='Quiet'?`background-image:url('${root}shared/design/assets/backgrounds/miqat_quiet.jpg')`:c[0]==='Aurora sky'?`background-image:url('${root}shared/design/assets/backgrounds/aurora_sky.jpg')`:c[0]==='Dusk peaks'?`background-image:url('${root}shared/design/assets/backgrounds/dusk_peaks.jpg')`:''}" class="artthumb ${c[0]==='Plain'?'solid':''}"></span>`}<span class="caption">${c[0]}</span></button>`).join('')}</div>`;
}
function widget(layout='day') {return `<div class="widget-preview" data-widget-preview><small data-widget-hijri>11 Jumada II 1448 AH · Cairo</small><small data-widget-gregorian hidden>21 November 2026</small><div class="big">Dhuhr <span style="float:right">11:41</span></div><small>Next prayer · in 24 minutes</small>${layout==='next'?'':`<div class="mini-prayers">${prayerNames.map((n,i)=>`<span>${n}<b>${times[i]}</b></span>`).join('')}</div>`}</div>`;}
function sheet(content, foot = '', base = '') {return `<div class="content">${base || '<h2>Settings</h2>'+group(row('Location & calculation','Cairo','location')+row('Prayer alerts','','alerts'))}</div><div class="sheet-demo"><section class="sheet" aria-label="Dialog"><div class="handle"></div>${content}${foot}</section></div>`;}
const pages=[];
function page(id, journey, title, note, content, foot = '', extra = '', back='settings') {pages.push({id,journey,title,note,content,foot,extra,back});}

page('welcome','01 · First use','Welcome','Feedback 1. One warm introduction; setup starts after Get started.',`<div class="content welcome"><div class="welcome-copy"><img class="brandmark" src="${root}shared/design/assets/qr-mark.png" alt="Miqat"><h2>Welcome to Miqat</h2><p>Make room for prayer.</p><p>Prayer times, adhan and a little calm throughout your day — on your phone and your TV.</p></div></div>`,footer('Get started','setup-location','Explore first','home'),'art welcome-page','home');
page('setup-location','01 · First use','Your location & alerts','Feedback 2–3. Country and city are labeled. One confirmation; no prayer-alert toggle.',`<div class="content"><p class="step">SETUP · 1 OF 2</p><h2>Your location & alerts</h2><p class="sub">Set where Miqat calculates your prayer times.</p>${group(`<div style="padding:4px 16px 14px">${locationFields()}</div>`)}</div>`,footer('Confirm location','notification-request','Set up later','setup-style'),'art','welcome');
page('countries','01 · First use','Choose country','Searchable popup; changing country clears an incompatible city.',sheet(`<h2>Choose country</h2><input class="searchfield" placeholder="Search countries" aria-label="Search countries" data-filter>${group(['Egypt','Indonesia','Saudi Arabia','Türkiye','United Kingdom','United States'].map(n=>row(n,n==='Egypt'?'Selected':'','setup-location')).join(''))}`,`<footer class="foot">${go('setup-location','Cancel','text')}</footer>`),'','','setup-location');
page('cities','01 · First use','Choose city','Country limits the list. Search remains visible. Coordinates are available separately.',sheet(`<h2>City in Egypt</h2><input class="searchfield" placeholder="Search cities" aria-label="Search cities" data-filter>${group(['Alexandria','Aswan','Cairo','Giza','Luxor','Port Said'].map(n=>row(n,n==='Cairo'?'Selected':'','setup-location')).join(''))}`,`<footer class="foot">${go('setup-location','Cancel','text')}</footer>`),'','','setup-location');
page('detected','01 · First use','Location detected','Feedback 2. The icon fills country and city. Exact coordinates remain authoritative; city is a label.',`<div class="content"><p class="step">SETUP · 1 OF 2</p><h2>Your location & alerts</h2><p class="sub">Review the location before confirming.</p>${group(`<div style="padding:4px 16px 14px">${locationFields()}</div>`)}${status('<strong>Location found · near Cairo, Egypt</strong><br>Country and nearest city filled from your position.','check')}${go('location-advanced','Review coordinates','text')}</div>`,footer('Confirm location','notification-request'),'art','setup-location');
page('location-error','01 · First use','Location unavailable','Declining location leaves manual country/city fully usable. No repeated permission request.',`<div class="content"><h2>Your location & alerts</h2>${status('<strong>Location access wasn’t allowed.</strong><br>Choose a country and city to continue.','compass')}${group(`<div style="padding:4px 16px 14px">${locationFields()}</div>`)}${action('Open location settings','text','Would open Android app settings after your explicit tap.')}</div>`,footer('Confirm location','notification-request'),'art','setup-location');
page('notification-request','01 · First use','Android notification request','Feedback 3. Illustrated OS prompt, not a custom permission wall. Denial advances setup.',`<div class="content"><h2>Your location & alerts</h2>${status('Cairo, Egypt confirmed.','check')}</div><div class="sheet-demo" style="align-items:center"><div class="permission"><span class="os-label">ANDROID SYSTEM PROMPT · ILLUSTRATION</span><h2>Allow Miqat to send you notifications?</h2><button data-go="setup-style">Allow</button><button data-go="notifications-denied">Don’t allow</button></div></div>`,'','art','setup-location');
page('notifications-denied','01 · First use','Permission declined','A no stays no. No repeat prompt or exact-alarm request. Continue straight to style.',`<div class="content"><p class="step">SETUP · 1 OF 2</p><h2>Location set.</h2>${status('<strong>Prayer notifications are off.</strong><br>You can still use prayer times and widgets.','bell')}${hero('Alerts off')}<p class="sub">You can change notification access later in Settings.</p></div>`,footer('Continue','setup-style'),'art','setup-location');
function styleContent(setup,background=false) {return `<div class="preview-content"><p class="step">${setup?'SETUP · 2 OF 2':'LIVE APP PREVIEW'}</p><h2>Your style</h2><p class="sub">${setup?'A little calm, your way.':'Preview your changes across the whole page.'}</p>${hero()}${group(row('Fajr','04:51','','fajr')+row('Dhuhr','11:41','','dhuhr'))}</div><div class="palette-controls">${seg('Appearance view',['Theme','Background'],background?'Background':'Theme')}<div data-style-rail>${styleRail(background?'Background':'Theme')}</div><p class="style-note">${setup?'Change this any time in Settings.':'Changes are kept only when you apply.'}</p></div>`;}
page('setup-style','01 · First use','Style · full page','Feedback 4. Every surface, label and button previews the selected theme. Filled rail cards separate labels from artwork.',styleContent(true),footer('Start using Miqat','home'),'art','setup-location');
page('home','02 · Daily use','Prayer home','The existing product remains prayer first. Schedule and widget entry points are visible.',`<div class="content"><button class="date-link" data-go="calendar">11 Jumada II 1448 AH · Saturday</button><h2>Peace in your day.</h2>${row('Cairo, Egypt','Change','location','compass')}${hero()}${prayers()}${group(row('Hijri calendar','Jumada II 1448','calendar','clock')+row('Qibla','','qibla','compass')+row('Widgets','Customize & add','widgets','mihrab'))}<h3>More from Miqat</h3>${group(row('Quran','Coming soon','coming-soon','lock')+row('Adhkar','Coming soon','coming-soon','lock'))}</div>`,nav(),'art','welcome');
page('qibla','02 · Daily use','Qibla · compass','Sensor heading uses the saved position; map mode shows the calculated route. Approximate positions are labeled and cannot improve sensor accuracy.',`<div class="content"><h2>Qibla</h2><div class="action-grid">${go('qibla','Compass','primary')}${go('qibla-map','Map')}</div><p class="sub">Cairo, Egypt</p><div class="qibla">${icon('compass')}</div><div class="center"><h2>${Math.round(qiblaBearing(30.0444,31.2357))}°</h2><p class="sub">From true north</p></div>${status('Calibrate your compass if the direction is unstable.','compass')}${go('qibla-unavailable','Sensor unavailable state','text')}</div>`,'','','home');
page('qibla-unavailable','02 · Daily use','Qibla · no sensor','Bearing is still useful when a live heading is unavailable.',`<div class="content"><h2>Qibla</h2><div class="empty">${icon('compass')}<h2>Live compass unavailable</h2><p>This phone has no supported orientation sensor.</p></div>${group(row('Direction from Cairo',Math.round(qiblaBearing(30.0444,31.2357))+'° true north'))}${go('qibla-map','View map','primary')}</div>`,'','','qibla');
page('adhan','02 · Daily use','Adhan playing','Keep real playback controls and accessible Stop. Background audio is unaffected by navigating away.',`<div class="content sound"><h2>Dhuhr</h2><p class="sub">11:41 · Hamdan Al-Malki</p><div class="progress"><span></span></div><p class="sub">00:42 / 03:16</p><div class="playback">${action('Pause','','Playback paused · demonstration')}${action('Stop','','Playback stopped · demonstration')}</div></div><footer class="foot">${action('Swipe up to stop','text','Native swipe handle; accessible Stop remains available.')}${go('home','Return to Prayer','text')}</footer>`,'','art','home');
page('coming-soon','02 · Daily use','Unavailable module','Existing locked modules get an honest brief explanation; no new scope.',sheet(`<h2>Coming soon</h2><p class="sub">This feature isn’t available in this version of Miqat.</p>`,go('home','Back to Prayer','primary')),'','','home');
page('settings','03 · Phone settings','Settings','Feedback 11. Widgets has a first-class entry. Phone settings stay distinct from TV settings.',`<div class="content"><h2>Settings</h2><p class="sub">On this phone</p>${group(row('Location & calculation','Cairo, Egypt','location','compass')+row('Prayer alerts','Per-prayer sound & days','alerts','bell')+row('Appearance','Miqat · Signature','appearance','image')+row('Widgets','Customize & add','widgets','mihrab'))}${group(row('Permissions','Review access','permissions','lock')+row('Language','English','language','globe')+row('Guided setup','Start again','welcome','refresh'))}${group(row('Reset phone prayer settings','','reset','refresh'))}</div>`,nav('Settings'),'','home');
page('location','03 · Phone settings','Location & calculation','Feedback 6–7. Compact location icon, advanced dialog and visible short choices. No horizontal overflow.',`<div class="content"><h2>Location & calculation</h2>${group(`<div style="padding:4px 16px 14px">${locationFields()}</div>`)}${group(row('Advanced location','Coordinates & timezone','location-advanced'))}<h3>Calculation method</h3>${group(row('Egyptian General Authority of Survey','','methods'))}<h3>Asr school</h3>${seg('Asr school',['Standard','Hanafi'])}<h3>High-latitude rule</h3>${seg('High-latitude rule',['Middle of the night','Seventh of the night','Angle based'],'Middle of the night',true)}${group(num('Sunrise adjustment',0)+num('Hijri adjustment',0,'days',-2,2)+toggle('Update location on opening'))}</div>`,apply('Save location','settings'),'','settings');
page('location-advanced','03 · Phone settings','Advanced location dialog','Feedback 7. Coordinates and timezone have their own bounded popup. Cancel discards the draft.',sheet(`<h2>Advanced location</h2>${field('Latitude','30.0444','number')}${field('Longitude','31.2357','number')}${selectrow('Prayer timezone','Africa/Cairo','timezones')}<p class="sub">Manual coordinates override the city position.</p>`,apply('Use this location','location')),'','','location');
page('methods','03 · Phone settings','Calculation method picker','Long lists are searchable, selected value remains marked; no carousel.',sheet(`<h2>Calculation method</h2><input class="searchfield" aria-label="Search methods" placeholder="Search methods" data-filter>${group(['Egyptian General Authority of Survey','Muslim World League','Umm al-Qura University, Makkah','University of Islamic Sciences, Karachi','North America'].map((n,i)=>row(n,i?'':'Selected','location')).join(''))}`,go('location','Cancel','text')),'','','location');
page('timezones','03 · Phone settings','Timezone picker','The city’s prayer zone is explicit. Phone timezone is an intentional choice, not a hidden assumption.',sheet(`<h2>Prayer timezone</h2><input class="searchfield" placeholder="Search timezones" aria-label="Search timezones" data-filter>${group(['Use phone timezone','Africa/Cairo','Asia/Riyadh','Europe/London','America/New_York'].map(n=>row(n,n==='Africa/Cairo'?'Selected':'','location-advanced')).join(''))}`,go('location-advanced','Cancel','text')),'','','location-advanced');
page('alerts','03 · Phone settings','Prayer alerts','Notifications carry every enabled prayer alert. Adhan, Short tone and Silent select its sound; the screen is independent.',`<div class="content"><h2>Prayer alerts</h2>${group(prayerNames.map(n=>row(n,'Adhan',`prayer-${n.toLowerCase()}`,n.toLowerCase())).join(''))}${group(row('Default audio','Voice, level & length','audio-defaults','speaker')+toggle('Show adhan screen')+row('Permissions & delivery','','permissions','lock'))}</div>`,apply(),'','settings');
function prayerEditor(name,enabled=true) {
 return `<div class="content"><div class="prayer-heading"><h2>${icon(name.toLowerCase())}${name}</h2><button class="switch" role="switch" aria-label="Enable ${name} alerts" aria-checked="${enabled}" data-prayer-enabled><span></span></button></div><fieldset class="prayer-config" ${enabled?'':'disabled'}><legend class="sr-only">${name} alert settings</legend><h3>Sound</h3>${seg('Alert type',['Adhan','Short tone','Silent'])}${group(toggle('Vibrate')+row('Vibration','Double pulse'))}<h3>Repeat on</h3>${days()}${group(row('Day overrides','Mon–Fri · Silent','schedule','clock'))}${group(num('Time adjustment',0)+num('Remind before',0,'min',0,60)+num('Remind after',0,'min',0,60))}<section data-adhan-audio><h3>Adhan audio</h3>${group(row('Voice',name==='Fajr'?'Malek Chebae (Fajr)':'Hamdan Al-Malki','voices'))}${group(num('Adhan level',70,'%',0,100,5))}${lengthControl(name==='Fajr'?'chebae_fajr':'almalki')}</section></fieldset></div>`;
}
for (const name of prayerNames) {
 page(`prayer-${name.toLowerCase()}`,'03 · Phone settings',`${name} settings`,'An enable switch beside the prayer disables all configuration. Sound has three choices; vibration is independent. Day overrides belong to this prayer.',prayerEditor(name),apply('Save prayer','alerts'),'','alerts');
}
page('prayer-disabled','03 · Phone settings','Prayer disabled','Disabled controls are unavailable to touch, keyboard and accessibility actions; the enable switch remains available.',prayerEditor('Fajr',false),apply('Save prayer','alerts'),'','alerts');
page('schedule','03 · Phone settings','Dhuhr · day overrides','One override per weekday for this prayer. No second global schedule or repeated voice/volume/length fields.',`<div class="content"><h2>Dhuhr · day overrides</h2>${group(weekdays.map((d,i)=>row(d,i<5?'Silent':'Use default','day-override')).join(''))}${go('schedule-today','This week’s alerts','text')}</div>`,apply('Save day overrides','prayer-dhuhr'),'','prayer-dhuhr');
page('schedule-today','03 · Phone settings','Dhuhr · weekly plan','Overrides change only the selected prayer and weekday; other days inherit its default.',`<div class="content"><h2>Dhuhr · this week</h2>${group(weekdays.map((d,i)=>row(d,i<5?'Silent':'Adhan')).join(''))}</div>`,'','','schedule');
page('audio-defaults','03 · Phone settings','Default audio','Percentage follows the selected recording’s duration. Ending preview is explicit and never autoplays.',`<div class="content"><h2>Default audio</h2>${group(row('Adhan voice','Hamdan Al-Malki','voices')+num('Adhan level',70,'%',0,100,5))}${lengthControl()}</div>`,apply('Save audio','alerts'),'','alerts');
page('voices','03 · Phone settings','Voice selection sheet','Keep search, explicit preview/Stop, custom import and Apply/Cancel. Selecting a voice never autoplays.',sheet(`<h2>Adhan voice</h2><input class="searchfield" aria-label="Search voices" placeholder="Search voices" data-filter>${group(row('Use default voice','Selected','audio-defaults')+row('Hamdan Al-Malki','','audio-defaults')+row('Mishary Al-Afasy','','audio-defaults')+row('Custom recording','','audio-import'))}${go('audio-import','Choose audio from device','text')}<div class="pair" style="display:flex;gap:12px">${action('Listen','','Preview · simulated')}${action('Stop','','Preview stopped · simulated')}</div>`,apply('Use voice','audio-defaults')),'','','audio-defaults');
page('audio-import','03 · Phone settings','Custom recording','Private system file picker and import failure are visible; no file is actually opened by this mock.',sheet(`<h2>Custom recording</h2><p class="sub">Choose an audio file stored on your phone.</p>${action('Choose audio file','','Would open Android’s document picker. No upload.')}${status('If a file can’t be read, your previous voice remains selected.','music')}`,apply('Cancel import','voices')),'','','voices');
page('adhan-options','03 · Phone settings','Adhan screen options','Optional screen is a toggle, separate from sound. Further Android access is requested only after choosing the feature.',`<div class="content"><h2>Adhan screen</h2>${group(toggle('Show adhan screen')+toggle('Stop with volume keys on adhan screen'))}${go('adhan','Preview screen','text')}</div>`,apply('Save options','alerts'),'','alerts');
page('appearance','03 · Phone settings','Appearance · theme','Feedback 4. Same full-page live preview as setup; Selections save immediately.',styleContent(false),'','art','settings');
page('appearance-background','03 · Phone settings','Appearance · background','Background rail uses opaque captions and frames. The page changes alongside the hero.',styleContent(false,true),'','art','appearance');
page('display','03 · Phone settings','Text & display','Small sets are connected, recessed controls, with check marks and outlines in selected state.',`<div class="content"><h2>Text & display</h2><h3>Clock</h3>${seg('Clock format',['24 hour','12 hour'])}<h3>Digits</h3>${seg('Digits',['Automatic','123','١٢٣'])}${group(num('Interface size',100,'%',80,150,10)+toggle('Reduce motion'))}${status('Large text can reflow labels while controls remain reachable.','image')}</div>`,apply('Save display','appearance'),'','appearance');
page('permissions','03 · Phone settings','Permissions & delivery','Outside onboarding. Current native scheduling requires exact access; removing that prerequisite needs delivery work before shipping.',`<div class="content"><h2>Permissions & delivery</h2>${group(row('Notifications','Allowed','permission-recovery','bell')+row('Location','While using app','permission-recovery','compass'))}<h3>If alerts are late or missing</h3>${group(row('Precise prayer timing','Review Android access','delivery-help','clock')+row('Full-screen adhan','Optional','adhan-options','image'))}</div>`,'','','settings');
page('permission-recovery','03 · Phone settings','Explicit access recovery','A declined permission is revisited only at the user’s request. No forced rerun of setup.',sheet(`<h2>Notification access</h2><p class="sub">Miqat notifications are off in Android Settings.</p>${action('Open Android Settings','primary','Would open this app’s Android notification settings.')}`,go('permissions','Back','text')),'','','permissions');
page('language','03 · Phone settings','Language','English review only. Production Arabic/RTL will require its own native validation.',`<div class="content"><h2>Language</h2>${seg('Language',['English','Arabic'],'English',true)}</div>`,apply('Save language','settings'),'','settings');
page('reset','03 · Phone settings','Reset confirmation','Preserve the destructive confirmation and paired TV separation.',sheet(`<h2>Reset phone prayer settings?</h2><p class="sub">This resets prayer locations, adjustments and alert preferences on this phone. Paired TVs remain connected.</p>${action('Reset phone prayer settings','danger','Reset simulated; no saved data exists in the mock.')}`,go('settings','Cancel','text')),'','','settings');

page('widgets','04 · Widgets','Widgets','Feedback 11. Settings → Widgets contains new and placed widgets; instances stay independent.',`<div class="content"><h2>Widgets</h2><p class="sub">Prayer times on your home screen.</p>${widget()}${go('widget-editor','Customize & add','primary')}<h3>On your home screen</h3>${group(row('Daily prayers|Miqat · Signature','Edit','widget-existing','mihrab')+row('Next prayer|Frost · Plain','Edit','widget-existing','clock'))}</div>`,'','','settings');
function widgetEditor(existing=false,layout='day') {return `<div class="content"><h2>${existing?'Edit widget':'Customize widget'}</h2>${widget(layout)}<h3>Layout</h3>${seg('Widget layout',['Next prayer','Daily prayers','Compact'],layout==='next'?'Next prayer':layout==='strip'?'Compact':'Daily prayers')}<h3>Theme</h3>${styleRail()}<h3>Background</h3>${styleRail('Background')}<h3>Shape</h3>${seg('Widget shape',['Rounded','Soft','Square'])}<label class="field"><span>Background opacity · <output data-opacity>100%</output></span><input class="range" type="range" min="0" max="100" value="100" aria-label="Background opacity"></label>${group(toggle('Hijri date',true)+toggle('Gregorian date'))}<h3>Text size</h3>${seg('Widget text size',['100%','120%'])}</div>`;}
page('widget-editor','04 · Widgets','Customize widget · daily','Short layout/shape sets are visible. Visual theme list alone scrolls horizontally.',widgetEditor(),footer('Add to home screen','widget-pin'),'','widgets');
page('widget-next','04 · Widgets','Customize widget · next','Each layout has a reviewable state; reuse one editor and preserve per-instance settings.',widgetEditor(false,'next'),footer('Add to home screen','widget-pin'),'','widgets');
page('widget-compact','04 · Widgets','Customize widget · compact','Compact preview retains five prayer names and times; native widget size remains launcher controlled.',widgetEditor(false,'strip'),footer('Add to home screen','widget-pin'),'','widgets');
page('widget-existing','04 · Widgets','Edit placed widget','Existing widget says Save widget, never Add; cancel leaves that instance unchanged.',widgetEditor(true),apply('Save widget','widgets'),'','widgets');
page('widget-pin','04 · Widgets','Android widget confirmation','The app requests pinning. Success is confirmed only by OS callback; this is an illustrative prompt.',sheet(`<h2>Add Miqat widget?</h2><span class="pill">ANDROID LAUNCHER · ILLUSTRATION</span>${widget()}<p class="sub">Your launcher chooses the final placement.</p>`,footer('Add','widget-added','Cancel','widget-editor')),'','','widget-editor');
page('widget-added','04 · Widgets','Widget added','Show success only after a valid OS confirmation, not immediately after requesting pin.',`<div class="content"><div class="empty">${icon('check')}<h2>Added to your home screen</h2><p>You can resize it from your launcher.</p></div>${widget()}${go('widgets','Done','primary')}</div>`,'','','widgets');
page('widget-fallback','04 · Widgets','Manual widget fallback','Launcher pinning is not universal. Preserve customization and show the shortest useful recovery.',sheet(`<h2>Add from your home screen</h2><p class="sub">This launcher doesn’t support adding a widget from Miqat.</p><ol class="steps"><li>Touch and hold an empty area on your home screen.</li><li>Open Widgets and choose Miqat.</li><li>Choose your widget and customize it.</li></ol>`,go('widgets','Done','primary')),'','','widget-editor');

page('tvs','05 · TV setup','Your TVs · empty','Feedback 5. Only implemented TV systems lead to setup. No Other or Coming soon platform dead ends.',`<div class="content"><h2>Your TVs</h2><div class="empty">${icon('tv')}<h2>Miqat, on your TV.</h2><p>Set up a supported TV or pair one that already has Miqat.</p></div>${go('tv-platform','Set up a TV','primary')}${go('pair','Miqat is already installed','text')}${go('tvs-paired','View paired-TV example','text')}</div>`,nav('Your TVs'),'','home');
page('tv-platform','05 · TV setup','Choose TV system','Only Android/Google TV and LG webOS exist in the code. Brand/model certification is not invented.',`<div class="content"><h2>Which TV system?</h2><p class="sub">Choose the system shown in your TV’s settings.</p>${group(row('Android / Google TV|Requires developer access','','android-guide','tv')+row('LG webOS|Requires LG Developer Mode','','lg-guide','tv'))}${status('Support depends on the TV’s system and developer access. A brand name alone doesn’t establish compatibility.','tv')}${go('pair','Miqat is already installed','text')}</div>`,'','','tvs');
const source = () => `<h3>App source</h3>${seg('Release channel',['Latest','Stable','Preview'])}${group(row('Advanced','Choose local APK / IPK','tv-local'))}`;
page('android-guide','05 · TV setup','Android / Google TV preparation','Numbered preparation remains on one page. Explicit connect → package review → installation.',`<div class="content"><h2>Prepare Android TV</h2><ol class="steps"><li>Connect phone and TV to the same home network.</li><li>Enable Developer options.<small>On the TV: Settings → About → select the build number repeatedly.</small></li><li>Enable network or wireless debugging.<small>Names and access vary by TV. Find its address in network settings.</small></li><li>Keep the TV on for its connection approval.</li></ol>${field('TV address','192.0.2.10')}${source()}${status('Connect opens the existing guarded Android installer. Pairing for TV control happens separately.','lock')}</div>`,footer('Connect to TV','installer-find'),'','tv-platform');
page('android-access','05 · TV setup','Android connection approval','Installation access is separate from Miqat companion trust. Real TV authorization is never faked.',`<div class="content"><h2>Approve on your TV</h2>${status('<strong>Waiting for debugging approval</strong><br>Approve this phone on your TV screen.','lock')}<ol class="steps"><li>Check that the TV address is correct.</li><li>Review the TV’s connection request.</li><li>Allow only the phone you are setting up now.</li></ol>${go('installer-package','Preview approved state','text')}</div>`,footer('Cancel','android-guide'),'','android-guide');
page('lg-guide','05 · TV setup','LG webOS preparation','Preparation, source, address and passphrase stay together. No fictional one-tap LG setup.',`<div class="content"><h2>Prepare LG webOS</h2><ol class="steps"><li>Connect phone and TV to the same home network.</li><li>Open LG Developer Mode on the TV.<small>Install it from LG’s store and sign in if needed.</small></li><li>Enable Developer Mode and follow the TV’s restart instructions.</li><li>Turn on Key Server.<small>Keep the TV’s IP address and passphrase ready.</small></li></ol>${field('TV address','192.0.2.11')}${field('Developer Mode passphrase','','password')}${source()}${status('LG Developer Mode needs renewal. Miqat does not replace LG Home or wake the TV from standby.','tv')}</div>`,footer('Connect to TV','lg-trust'),'','tv-platform');
page('lg-trust','05 · TV setup','LG identity confirmation','Retain explicit SSH identity approval before install credentials are trusted. No real host data in mock.',sheet(`<h2>Trust this TV?</h2><p class="sub">LG webOS · 192.0.2.11</p>${status('Compare the reported identity before continuing.','lock')}<p class="sub" style="overflow-wrap:anywhere">SHA256: EXAMPLE-FINGERPRINT-FOR-DESIGN-ONLY</p><p class="sub">If this identity changes later, stop and verify the TV.</p>`,footer('Trust & continue','package-review','Cancel','lg-guide')),'','','lg-guide');
page('tv-local','05 · TV setup','Local package source','An explicit local source remains usable when no public release exists.',sheet(`<h2>Local package</h2><p class="sub">Use a reviewed APK for Android TV or IPK for LG webOS.</p>${action('Choose local package','','Would open Android’s document picker.')}${group(row('Selected file','Miqat-review.ipk'))}${status('A package is reviewed before installation. Selecting a file does not install it.','folder')}`,footer('Review package','package-review','Cancel','tv-platform')),'','','tv-platform');
page('release-unavailable','05 · TV setup','Public release unavailable','Current project docs say no public release is published. Never claim Latest is downloadable.',`<div class="content"><h2>No public build available</h2><p class="sub">There isn’t a downloadable release in this channel yet.</p>${group(row('Release channel','Latest','tv-platform')+row('Use a local package','','tv-local','folder'))}${action('Try again','','Would retry the selected public release channel.')}</div>`,'','','tv-platform');
page('package-review','05 · TV setup','Review before install','Explicit installation after package integrity and version checks; fixtures are clearly labeled.',`<div class="content"><h2>Ready to install</h2><p class="sub">Design example · local review package</p>${group(row('TV system','LG webOS')+row('Source','Local IPK')+row('Package identity','tv.miqat.webos')+row('Integrity','Verified · example')+row('Version check','No downgrade · example'))}${status('Keep the TV and phone connected until installation finishes.','wifi')}</div>`,footer('Install on TV','installing','Cancel','tv-platform'),'','tv-platform');
page('installing','05 · TV setup','Installation progress','Operational progress has a persistent title and cancel. No decorative auto-completion.',`<div class="content"><h2>Installing Miqat</h2><p class="sub">LG webOS</p>${group(row('Connect to TV','Complete')+row('Verify package','Complete')+row('Install package','In progress')+row('Launch Miqat','Waiting'))}<div class="progress"><span></span></div>${go('installed','Preview success','text')}${go('install-error','Preview failure','text')}</div>`,footer('Cancel installation','install-error'),'','package-review');
page('installed','05 · TV setup','Installed · ready to pair','Installation completion does not imply paired control access.',`<div class="content"><div class="empty">${icon('check')}<h2>Miqat is on your TV.</h2><p>Open Miqat on the TV, then open its phone-pairing page.</p></div></div>`,footer('Pair this phone','pair','Done for now','tvs'),'','tvs');
page('install-error','05 · TV setup','Installation interrupted','Preserve failure message and recovery; cancellation isn’t labeled installation success.',`<div class="content"><h2>Installation not completed</h2>${status('The connection ended before installation was confirmed.','wifi')}<p class="sub">Check the TV and network, then reconnect to inspect its installed state.</p>${go('lg-guide','Reconnect','primary')}${go('tvs','Return to Your TVs','text')}</div>`,'','','tvs');
page('pair','05 · TV setup','Pair an installed TV','Camera and manual entry both remain. Permission occurs only when Scan is tapped.',`<div class="content"><h2>Pair your TV</h2><ol class="steps"><li>On your TV, open Miqat.</li><li>Open Settings → Pair phone.</li><li>Scan the QR shown there.</li></ol>${go('scanner','Scan TV QR','primary')}${go('manual-pair','Enter pairing details','text')}${status('Phone and TV must be on the same home network. Pairing needs approval on the TV.','lock')}</div>`,'','','tvs');
page('scanner','05 · TV setup','QR scanner','The camera area is a labeled design placeholder, not an invented QR or credential.',`<div class="content"><h2>Scan TV QR</h2><p class="sub">Point your camera at the QR on your TV.</p><div class="camera"><div>${icon('scan')}<p>Camera preview · simulated</p></div></div>${go('pair-approval','Preview detected QR','text')}${go('manual-pair','Enter details instead','text')}</div>`,footer('Cancel','pair'),'','pair');
page('manual-pair','05 · TV setup','Manual pairing','Transport remains pinned and authenticated. Manual details never bypass certificate validation.',`<div class="content"><h2>Pairing details</h2>${field('TV address','192.0.2.11')}${field('Pairing data from TV','')}<p class="sub">Use the complete pairing details shown by Miqat on your TV.</p></div>`,footer('Connect','pair-approval','Cancel','pair'),'','pair');
page('pair-approval','05 · TV setup','TV pairing approval','Match code then approve physically on TV. Cancel and rejection remain first-class states.',`<div class="content"><h2>Approve on your TV</h2>${group(row('TV found','Complete')+row('Secure connection','Complete')+row('TV approval','Waiting'))}<p class="sub">Check this code matches the one on your TV.</p><div class="code">284 716</div><p class="sub center" style="margin-top:20px">Waiting for approval on TV…</p>${go('tvs-paired','Preview approved state','text')}${go('pair-failure','Preview rejected or expired state','text')}</div>`,footer('Cancel','pair'),'','pair');
page('pair-failure','05 · TV setup','Pairing rejected or expired','Retry restarts explicit pairing; nothing is silently trusted.',`<div class="content"><h2>Pairing wasn’t completed</h2>${status('The TV rejected the request or the pairing code expired.','lock')}${go('pair','Try again','primary')}${go('tvs','Back to Your TVs','text')}</div>`,'','','pair');

page('tvs-paired','06 · TV controls','Your TVs · paired','Keep one setup entry and clear connection state. Offline records retain their identity.',`<div class="content"><h2>Your TVs</h2>${group(row('Living room|LG webOS · Connected','','tv-remote','tv')+row('Bedroom|Android TV · Offline','','tv-offline','tv'))}${go('tv-platform','Set up another TV','primary')}${go('pair','Pair installed Miqat','text')}</div>`,nav('Your TVs'),'','tvs');
page('tv-remote','06 · TV controls','TV remote','The current app refreshes media state on entry and after commands, not continuously. Paired horizontal Play/Stop icons remain usable when a snapshot becomes stale.',`<div class="content"><h2>Living room</h2><p class="sub">LG webOS</p><div class="action-grid">${action('Show Miqat','primary','TV Home simulated')}${go('tv-inputs','Inputs')}</div>${group(mediaControls('radio','Radio','radio')+mediaControls('adhan','Adhan preview','bell'))}${group(row('TV settings','','tv-settings','gear')+row('TV actions','','tv-actions','remote')+row('Manage TV','','tv-manage','more'))}</div>`,'','','tvs-paired');
page('tv-actions','06 · TV controls','TV actions','Navigation uses simple separated rows. No touching stack of command buttons.',`<div class="content"><h2>TV actions</h2>${group(row('Inputs','HDMI 1','tv-inputs','input')+row('Radio','','tv-radio','radio')+row('TV tests','','tv-tests','speaker'))}</div>`,'','','tv-remote');
page('tv-offline','06 · TV controls','Offline TV','Retained cached values are labeled and read-only; reconnect never uploads drafts.',`<div class="content"><h2>Bedroom</h2><p class="sub">Android TV · Offline</p>${status('Connect to the same home network and open Miqat on your TV.','wifi')}${action('Reconnect','primary','Reconnect simulated; drafts are not uploaded.')}${group(row('Last read settings','Read-only','tv-settings-stale')+row('Manage TV','','tv-manage'))}</div>`,'','','tvs-paired');
page('tv-settings-stale','06 · TV controls','Cached TV settings','Read-only cache; no active editing controls until refreshed.',`<div class="content"><h2>TV settings</h2>${status('<strong>Last read values · read-only</strong><br>Refresh while connected before editing.','lock')}${group(row('Location','Cairo')+row('Theme','Miqat')+row('Adhan','Enabled'))}${action('Refresh from TV','primary','Would read current TV values; never sends settings.')}</div>`,'','','tv-offline');
page('tv-settings','06 · TV controls','TV settings index','Capability-filtered categories; Android-only pages below are labeled. Snapshot read happens on entry.',`<div class="content"><p class="step">LIVING ROOM · LG WEBOS</p><h2>TV settings</h2>${group([['Prayer & calculation','tv-prayer'],['Prayer adjustments','tv-offsets'],['Adhan & reminders','tv-reminders'],['Per-prayer adhan','tv-prayer-day'],['Appearance','tv-appearance'],['Display','tv-display'],['Radio','tv-radio'],['Network','tv-network'],['Device','tv-device'],['TV tests','tv-tests'],['Paired phones','tv-pairing']].map(([n,id])=>row(n,'',id)).join(''))}</div>`,'','','tv-remote');
page('tv-prayer','06 · TV controls','TV · prayer','Existing TV controls, with compact choice sets and one-line numbers; no phone schedule sent to TV.',`<div class="content"><h2>Prayer · TV</h2>${group(row('Location','Cairo','cities')+row('Calculation method','Egyptian','methods'))}<h3>Asr school</h3>${seg('TV Asr school',['Standard','Hanafi'])}${group(row('Timezone','Africa/Cairo','timezones')+num('Hijri adjustment',0,'days',-2,2)+num('Facing adjustment',0,'degrees',-180,180)+row('Prayer adjustments','','tv-offsets')+row('Today’s prayers','','tv-today')+row('Compare online','Manual advisory only','tv-online'))}</div>`,apply('Save on TV','tv-settings'),'','tv-settings');
page('tv-offsets','06 · TV controls','TV · prayer adjustments','All six offsets stay inline, including informational sunrise. Keep reset confirmation.',`<div class="content"><h2>Prayer adjustments · TV</h2>${group(['Fajr','Sunrise','Dhuhr','Asr','Maghrib','Isha'].map(n=>num(n,0)).join(''))}${go('tv-reset','Reset adjustments','text')}</div>`,apply('Save on TV','tv-settings'),'','tv-settings');
page('tv-today','06 · TV controls','TV · today’s schedule','Existing read-only TV schedule. No recalculation asserted by the phone mock.',`<div class="content"><h2>Today’s prayers · TV</h2><p class="sub">Read from Living room · example data</p>${group(row('Fajr','04:51','','fajr')+row('Sunrise','06:20','','sunrise')+prayerNames.slice(1).map((n,i)=>row(n,times[i+1],'',n.toLowerCase())).join(''))}</div>`,'','','tv-prayer');
page('tv-online','06 · TV controls','TV · manual comparison','Keep networking explicit and advisory. No automatic schedule replacement.',`<div class="content"><h2>Prayer comparison</h2><p class="sub">Manually compare your configured times with an online source.</p>${status('Results are advisory. Your calculation method and adjustments will not be replaced.','globe')}${action('Compare now','primary','Manual comparison simulated; no network request is made.')}</div>`,'','','tv-prayer');
page('tv-reminders','06 · TV controls','TV · reminders','Existing TV reminder contract remains independent of the proposed phone exception schedule.',`<div class="content"><h2>Adhan & reminders · TV</h2>${group(toggle('Prayer alerts',true)+num('Remind before',5,'min',0,60)+toggle('Spoken reminder')+toggle('Adhan',true)+toggle('Prayer announcement')+row('Default voice','Hamdan Al-Malki','voices')+row('Fajr voice','Malek Chebae (Fajr)','voices')+num('Adhan level',70,'%',0,100,5)+num('Close after',0,'sec',0,600,30)+row('Per-prayer adhan','','tv-prayer-day')+row('TV tests','','tv-tests'))}</div>`,apply('Save on TV','tv-settings'),'','tv-settings');
page('tv-prayer-day','06 · TV controls','TV · per-prayer adhan','Existing five TV choices use visible switches, no new phone policy exported.',`<div class="content"><h2>Per-prayer adhan · TV</h2>${group(prayerNames.map(n=>toggle(n,true)).join(''))}</div>`,apply('Save on TV','tv-settings'),'','tv-settings');
page('tv-appearance','06 · TV controls','TV · appearance','Representative TV preview stays separate from full-page PHONE theme preview. Selections save directly to this TV.',`<div class="content"><h2>Appearance · TV</h2><span class="pill">REPRESENTATIVE TV PREVIEW</span>${hero()}<h3>Theme</h3>${styleRail()}<h3>Background</h3>${styleRail('Background')}${group(toggle('Countdown',true)+row('Mihrab position','Center','tv-choice')+row('Prayer layout','Balanced','tv-choice')+toggle('Show favourite apps',true)+num('Mihrab opacity',100,'%',50,100,5)+num('Lighting',18,'%',0,100)+toggle('Cycle appearance')+toggle('Focus lighting',true)+toggle('Reduce motion')+row('Custom theme colors','','tv-custom-theme')+row('Reset appearance','','tv-reset'))}</div>`,'','','tv-settings');
page('tv-display','06 · TV controls','TV · display','Show only capabilities supplied by selected TV. Android-only system-app visibility is absent in this LG example.',`<div class="content"><h2>Display · TV</h2><h3>Language</h3>${seg('TV language',['System','English','Arabic'])}<h3>Digits</h3>${seg('TV digits',['Automatic','123','١٢٣'])}<h3>Clock</h3>${seg('TV clock',['24 hour','12 hour'])}${group(num('Interface size',100,'%',80,150,10)+toggle('Quick labels',true)+row('Compact bar mode','Automatic','tv-choice')+row('Compact bar position','Top','tv-choice')+num('Compact bar timeout',10,'sec',0,120)+row('Show compact bar','','tv-actions')+row('Show clock','','tv-actions'))}</div>`,apply('Save on TV','tv-settings'),'','tv-settings');
page('tv-radio','06 · TV controls','TV · radio','Explicit playback actions; small sets visible, station lists searchable.',`<div class="content"><h2>Radio · TV</h2>${group(row('Station','Quran radio','tv-stations')+row('Playback mode','Audio only','tv-choice')+toggle('Resume radio')+toggle('Turn screen off while listening'))}${group(mediaControls('radio','Radio','radio'))}</div>`,apply('Save on TV','tv-settings'),'','tv-settings');
page('tv-stations','06 · TV controls','TV · station picker','Searchable list pattern reused for long catalogs.',sheet(`<h2>Radio station</h2><input class="searchfield" aria-label="Search stations" placeholder="Search stations" data-filter>${group(row('Quran radio','Selected','tv-radio')+row('Recitation station','','tv-radio'))}`,go('tv-radio','Cancel','text')),'','','tv-radio');
page('tv-network','06 · TV controls','TV · network','Network settings are opened on TV when offered. No new phone network privileges.',`<div class="content"><h2>Network · TV</h2>${status('Phone and TV communicate only on your home network.','wifi')}${action('Show TV instructions','primary','On the TV, use your remote to open Settings → Network.')}</div>`,'','','tv-settings');
page('tv-device','06 · TV controls','TV · device','LG example hides Android-only Home, apps and repair operations. No standby-wake claim.',`<div class="content"><h2>Device · LG webOS</h2>${group(row('Inputs','','tv-inputs')+row('Exit input','','tv-actions')+row('Paired phones','','tv-pairing'))}${action('TV settings instructions','','Use your physical TV remote to open system Settings.')}<h3>Android / Google TV only</h3>${go('tv-device-android','Review Android device page','text')}</div>`,'','','tv-settings');
page('tv-device-android','06 · TV controls','TV · Android device','Separate capability-specific mock. No promise every Android firmware supports every action.',`<div class="content"><p class="step">BEDROOM · ANDROID TV EXAMPLE</p><h2>Device · Android TV</h2>${group(row('Apps','','tv-apps')+row('Favourite apps','','tv-favourites')+row('Inputs','','tv-inputs')+row('Remote shortcuts','','tv-shortcuts')+row('Service health','','tv-health')+row('Screensaver','','tv-actions')+toggle('Startup')+toggle('Remote shortcuts',true)+row('Advanced redirects','','tv-redirects'))}${action('Open system Home','','TV Home simulated')}${action('TV system settings instructions','','Use your physical TV remote to open system Settings.')}</div>`,'','','tv-device');
page('tv-inputs','06 · TV controls','TV · inputs','Inputs come from the TV, not a hard-coded compatibility list.',`<div class="content"><h2>Inputs</h2>${group(row('HDMI 1','Current','tv-remote','input')+row('HDMI 2','','tv-remote','input'))}</div>`,'','','tv-actions');
page('tv-tests','06 · TV controls','TV · tests','Preserve bounded audition/Stop. Audible native tests will need a ready watcher.',`<div class="content"><h2>TV tests</h2>${group(row('Prayer','Dhuhr','tv-choice'))}${group(['Reminder banner','Prayer card','Short adhan preview','Full adhan','Spoken reminder','Prayer announcement','Background'].map(n=>row(n,'','tv-test-run')).join(''))}</div>`,'','','tv-settings');
page('tv-pairing','06 · TV controls','TV · paired phones','Keep physical approval authority and explicit revocation.',`<div class="content"><h2>Paired phones · TV</h2>${group(row('This phone','Approved','tv-revoke','lock'))}${status('New phones must be approved using your TV remote.','lock')}${action('Open TV pairing page','primary','TV pairing page requested · simulated')}</div>`,'','','tv-settings');
page('tv-revoke','06 · TV controls','TV · revoke phone','Explicit destructive action, with the consequence stated first.',sheet(`<h2>Revoke this phone?</h2><p class="sub">This phone will lose access to the TV. Pair again using the TV remote to restore access.</p>${action('Revoke phone','danger','Revocation simulated.')}`,go('tv-pairing','Cancel','text')),'','','tv-pairing');
page('tv-manage','06 · TV controls','Manage TV','Rename, update status and Forget remain discoverable without duplicate setup CTAs.',`<div class="content"><h2>Manage Living room</h2>${group(row('Rename TV','','tv-rename')+row('Updates','','updates')+row('Forget TV','','tv-forget'))}</div>`,'','','tv-remote');
page('tv-rename','06 · TV controls','Rename TV','Local editable display name; pairing identity remains untouched.',sheet(`<h2>Rename TV</h2>${field('TV name','Living room')}`,apply('Save name','tv-manage')),'','','tv-manage');
page('tv-forget','06 · TV controls','Forget TV confirmation','Keep protected per-record removal. Never erase unrelated TVs or phone prayer settings.',sheet(`<h2>Forget Living room?</h2><p class="sub">Remove this TV’s pairing from this phone. You’ll need to pair again to control it.</p>${go('tvs','Forget TV','danger')}`,go('tv-manage','Cancel','text')),'','','tv-manage');
page('updates','06 · TV controls','TV updates','Honest existing support: no remote update operation is added in a design pass.',`<div class="content"><h2>TV updates</h2>${status('Remote updates aren’t available in this version.','tv')}${go('tv-platform','Open setup & package options','primary')}</div>`,'','','tv-manage');
page('tv-choice','06 · TV controls','TV short-choice editor','Shared small-set pattern replaces a generic horizontal carousel.',sheet(`<h2>Position</h2>${seg('Position',['Top','Center','Bottom'],'Center',true)}`,apply('Save on TV','tv-settings')),'','','tv-settings');
page('tv-custom-theme','06 · TV controls','TV custom colors','Existing advanced editable value retains validation and draft Apply/Cancel; no new theme system.',`<div class="content"><h2>Custom theme colors · TV</h2>${field('Accent','#E3C07D')}${field('Ground','#0A2D33')}${field('Surface','#123C42')}${field('Primary text','#F7F0DF')}${field('Secondary text','#ADC8C6')}${status('All required theme colors must be valid before applying.','image')}</div>`,apply('Apply to TV','tv-appearance'),'','tv-appearance');
page('tv-reset','06 · TV controls','TV reset confirmation','Scope-specific reset requires confirmation; production copy must name the exact setting group.',sheet(`<h2>Reset these TV settings?</h2><p class="sub">Restore defaults for this setting group on the selected TV.</p>${action('Reset this group','danger','Group reset simulated.')}`,go('tv-settings','Cancel','text')),'','','tv-settings');
page('tv-conflict','06 · TV controls','TV save conflict','Keep current values and draft conflict recovery. Never overwrite a TV-side change silently.',`<div class="content"><h2>Settings changed on TV</h2><p class="sub">Your change wasn’t applied because the TV has newer values.</p>${group(row('Adhan level on TV','60%')+row('Your draft','70%'))}${action('Read latest TV settings','primary','Would re-read TV values and preserve your draft for review.')}${go('tv-settings','Cancel draft','text')}</div>`,'','','tv-settings');
page('tv-apps','06 · TV controls','TV · apps (Android)','Android-only installed app list and uninstall handoff. No fictional apps or package commands are executed.',`<div class="content"><h2>Apps · Android TV</h2><input class="searchfield" aria-label="Search TV apps" placeholder="Search installed apps" data-filter>${group(row('YouTube','Installed','tv-uninstall')+row('Quran app','Installed','tv-uninstall'))}${group(toggle('Hide system apps',true))}</div>`,'','','tv-device-android');
page('tv-uninstall','06 · TV controls','TV · uninstall handoff','OS/TV authority owns uninstall; never turn a list tap into deletion.',sheet(`<h2>Uninstall app on TV?</h2><p class="sub">Review the selected app and finish confirmation on your TV.</p>${action('Open TV uninstall','danger','Would request the offered TV uninstall flow.')}`,go('tv-apps','Cancel','text')),'','','tv-apps');
page('tv-favourites','06 · TV controls','TV · favourite apps','Preserve add, replace, remove and order actions using an explicit selected row.',`<div class="content"><h2>Favourite apps · TV</h2>${group(row('1 · Quran app','Selected','tv-favourite-actions','star')+row('2 · YouTube','','tv-favourite-actions','star'))}${go('tv-apps','Add app','primary')}</div>`,'','','tv-device-android');
