page('tv-shortcuts','06 · TV controls','TV · remote shortcuts','Existing Android remote-button catalog; each long action list opens a searchable selector.',`<div class="content"><h2>Remote shortcuts · TV</h2>${group(['Settings shortcut','Settings','Input','TV','Red','Green','Yellow','Blue'].map(n=>row(n,'Default','tv-shortcut-choice')).join(''))}</div>`,apply('Save on TV','tv-settings'),'','tv-device-android');
