const keyPages=['welcome','setup-location','setup-style','home','settings','location','alerts','prayer-dhuhr','calendar','qibla-map','schedule','appearance','widgets','tv-platform'];
pages.sort((a,b)=>a.journey.localeCompare(b.journey)||(keyPages.includes(a.id)?keyPages.indexOf(a.id):1000)-(keyPages.includes(b.id)?keyPages.indexOf(b.id):1000));
let visible = [...pages], focus=false, current=0;
function render() {
  document.getElementById('boards').innerHTML = pages.map((p,i)=>`<article class="board" id="${p.id}" data-page="${p.id}"><div class="board-label"><span class="number">${String(i+1).padStart(2,'0')}</span><div><h2>${p.title}</h2><p>${p.journey}</p></div></div><section class="phone ${p.extra}" aria-label="${p.title}"><header class="appbar"><button class="iconbtn back" aria-label="Back" data-go="${p.back}">${icon('back')}</button><span class="brand">${p.id==='home'?`<img class="toolbar-mark" src="${root}shared/design/assets/qr-mark.png" alt="Miqat">`:p.id==='welcome'?'':'Miqat'}</span>${p.id==='appearance'||p.id==='appearance-background'?go('display','Text & display','text'):'<span class="tiny">DESIGN MOCK</span>'}</header>${p.content}${p.foot}</section><p class="annotation">${p.note}</p></article>`).join('');
  hydrateIcons();hydrateCalendars();refreshOverrideRows();
  const sel=document.getElementById('group');
  [...new Set(pages.map(p=>p.journey))].forEach(g=>sel.add(new Option(g,g)));
  update();
}
function update() {
  stopEndingPreview();
  const query=document.getElementById('search').value.toLowerCase(), category=document.getElementById('group').value;
  visible=pages.filter(p=>(category==='all'||p.journey===category)&&`${p.title} ${p.note} ${p.id}`.toLowerCase().includes(query));
  current=Math.max(0,Math.min(current,visible.length-1));
  document.body.classList.toggle('focus',focus);
  document.querySelectorAll('.board').forEach(b=>b.hidden=!visible.some(p=>p.id===b.id)||(focus&&visible[current]?.id!==b.id));
  document.getElementById('count').textContent=focus?`${visible.length?current+1:0} / ${visible.length} pages`:`${visible.length} / ${pages.length} pages`;
  document.getElementById('view').textContent=focus?'Show full gallery':'Focus one page';
  document.getElementById('view').setAttribute('aria-pressed',focus);
  document.getElementById('previous').hidden=!focus;document.getElementById('next').hidden=!focus;
  document.getElementById('previous').disabled=current===0;document.getElementById('next').disabled=current>=visible.length-1;
}
function navigate(id) {
  stopEndingPreview();
  if(!pages.some(p=>p.id===id))return;
  document.getElementById('search').value='';document.getElementById('group').value='all';
  visible=[...pages];current=pages.findIndex(p=>p.id===id);update();
  history.replaceState(null,'','#'+id);
  document.getElementById(id).scrollIntoView({block:'start'});
}
let toastTimer;
function toast(message) {const t=document.getElementById('toast');t.textContent=message;t.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.classList.remove('show'),3500);}
document.addEventListener('click',e=>{
  const button=e.target.closest('button');if(!button)return;
  if(button.dataset.month){const month=monthDays(calendarAnchor);calendarAnchor=new Date(+month[button.dataset.month==='1'?month.length-1:0]+(+button.dataset.month)*dayMillis);hydrateCalendars();return;}
  if(button.dataset.date){calendarSelected=new Date(button.dataset.date);hydrateCalendars();navigate('calendar-day');return;}
  if(button.dataset.day){calendarSelected=new Date(+calendarSelected+(+button.dataset.day)*dayMillis);calendarAnchor=new Date(calendarSelected);hydrateCalendars();return;}
  if(button.hasAttribute('data-preview-ending')){previewEnding(button);return;}
  if(button.hasAttribute('data-load-map')){const map=button.closest('.content').querySelector('.qibla-map');let remaining=4,failed=false;map.querySelectorAll('img[data-map-src]').forEach(img=>{img.onload=()=>{if(--remaining===0&&!failed)map.classList.add('loaded');};img.onerror=()=>{if(!failed)toast('Map unavailable. The bearing and compass remain usable.');failed=true;button.hidden=false;button.textContent='Try map again';};img.src=img.dataset.mapSrc;});button.hidden=true;return;}
  if(button.dataset.media){toast(button.dataset.mediaState==='play'?'TV playback request simulated.':'TV Stop request simulated.');return;}
  if(button.hasAttribute('data-prayer-enabled')){const enabled=button.getAttribute('aria-checked')!=='true';button.setAttribute('aria-checked',enabled);button.closest('.content').querySelector('fieldset').disabled=!enabled;stopEndingPreview();return;}

  if(button.dataset.go){
    const boardId=button.closest('.board')?.id;
    if(button.dataset.go==='schedule'&&boardId?.startsWith('prayer-')){overridePrayer=boardId.slice(7);overridePrayer=overridePrayer[0].toUpperCase()+overridePrayer.slice(1);refreshOverrideRows();}
    if(button.dataset.go==='day-override')openDayOverride(button.querySelector('strong').textContent);
    if(boardId==='day-override'&&button.classList.contains('primary'))saveDayOverride();
    navigate(button.dataset.go);return;
  }
  if(button.dataset.message){toast(button.dataset.message);return;}
  if(button.classList.contains('switch')){const enabled=button.getAttribute('aria-checked')!=='true';button.setAttribute('aria-checked',enabled);if(button.getAttribute('aria-label')==='Use prayer defaults')button.closest('.content').querySelector('fieldset').disabled=enabled;if(button.closest('.phone').querySelector('[data-widget-preview]')){const date=button.getAttribute('aria-label')==='Hijri date'?'[data-widget-hijri]':button.getAttribute('aria-label')==='Gregorian date'?'[data-widget-gregorian]':null;if(date)button.closest('.phone').querySelector(date).hidden=!enabled;}if(button.getAttribute('aria-label')==='Use default level & length'){let next=button.closest('.row').nextElementSibling;for(let i=0;i<2&&next;i++,next=next.nextElementSibling)next.querySelectorAll('button').forEach(b=>b.disabled=enabled);}return;}
  if(button.dataset.delta){const stepper=button.closest('.stepper'),output=stepper.querySelector('output');output.value=Math.max(+stepper.dataset.min,Math.min(+stepper.dataset.max,+output.value+(+button.dataset.delta)*(+stepper.dataset.step)));return;}
  if(button.closest('.days')){button.setAttribute('aria-pressed',button.getAttribute('aria-pressed')!=='true');return;}
  if(button.closest('.seg')){
    const parent=button.closest('.seg');parent.querySelectorAll('button').forEach(b=>b.setAttribute('aria-pressed',b===button));
    const label=parent.getAttribute('aria-label'),phone=parent.closest('.phone');
    if(label==='Alert type'){phone.querySelectorAll('[data-adhan-audio]').forEach(e=>{e.querySelectorAll('button,input').forEach(c=>c.disabled=button.textContent.trim()!=='Adhan');e.classList.toggle('inactive-audio',button.textContent.trim()!=='Adhan');});stopEndingPreview();}
    if(label==='Appearance view') phone.querySelector('[data-style-rail]').innerHTML=styleRail(button.textContent.trim());
    if(label==='Widget shape'){const w=phone.querySelector('[data-widget-preview]');w.classList.remove('rounded','soft','square');w.classList.add(button.textContent.trim().toLowerCase());}
    if(label==='Widget layout'){const dest={'Next prayer':'widget-next','Daily prayers':'widget-editor','Compact':'widget-compact'}[button.textContent.trim()];navigate(dest);}
    return;
  }
  if(button.dataset.theme){const phone=button.closest('.phone');const target=phone.querySelector('[data-widget-preview]')||(phone.closest('.board').id==='tv-appearance'?phone.querySelector('.hero'):phone);target.classList.remove('aurora','dusk','frost');if(button.dataset.theme!=='miqat')target.classList.add(button.dataset.theme);button.parentElement.querySelectorAll('button').forEach(b=>b.setAttribute('aria-pressed',b===button));return;}
  if(button.dataset.background){const phone=button.closest('.phone');const target=phone.querySelector('[data-widget-preview]')||(phone.closest('.board').id==='tv-appearance'?phone.querySelector('.hero'):phone);target.classList.toggle('plain',button.dataset.background==='plain');const image={signature:'phone/portrait/miqat_signature.png',quiet:'assets/backgrounds/miqat_quiet.jpg','aurora sky':'assets/backgrounds/aurora_sky.jpg','dusk peaks':'assets/backgrounds/dusk_peaks.jpg'}[button.dataset.background];target.style.setProperty('--art',image?`url('${root}shared/design/${image}')`:'none');target.classList.add('art');button.parentElement.querySelectorAll('button').forEach(b=>b.setAttribute('aria-pressed',b===button));}
});
document.addEventListener('input',e=>{
  if(e.target.matches('[data-filter]')) {const text=e.target.value.toLowerCase();e.target.parentElement.querySelectorAll('.group .row').forEach(r=>r.hidden=!r.textContent.toLowerCase().includes(text));}
  if(e.target.matches('[aria-label="Adhan length"]')){stopEndingPreview();const length=e.target.closest('.length-control');length.querySelector('[data-length-value]').value=e.target.value+'%'+(e.target.value==='100'?' · Full adhan':'');return;}
  if(e.target.matches('.range')) {const phone=e.target.closest('.phone');phone.querySelector('[data-opacity]').value=e.target.value+'%';phone.querySelector('[data-widget-preview]').style.setProperty('--widget-alpha',e.target.value/100);}
});
document.getElementById('search').addEventListener('input',()=>{current=0;update();});
document.getElementById('group').addEventListener('change',()=>{current=0;update();});
document.getElementById('view').onclick=()=>{focus=!focus;update();};
document.getElementById('previous').onclick=()=>{current--;update();};
document.getElementById('next').onclick=()=>{current++;update();};
Promise.all(['icons.json','prayer-icons.json'].map(file=>fetch(root+'shared/design/'+file).then(r=>{if(!r.ok)throw Error('Icon source unavailable');return r.json();}))).then(([general,prayer])=>{icons={...general,...Object.fromEntries(prayer.prayers.map(p=>[p.id,`<path d="${p.path}"/>`]))};render();if(location.hash)navigate(location.hash.slice(1));}).catch(err=>{document.getElementById('boards').textContent='Open through the local review server to load Miqat’s canonical assets. '+err.message;});
